const db=new RemoteD1Database(process.env.REPORT2_D1_BRIDGE_URL,process.env.REPORT2_D1_BRIDGE_TOKEN),now=Date.now(),id='RETAINED_CAPABILITY_COHORT:'+process.env.GITHUB_RUN_ID+':'+process.env.GITHUB_RUN_ATTEMPT,reservation={rows_read:4000,rows_written:8},sha=x=>createHash('sha256').update(x).digest('hex'),rows=x=>Array.isArray(x?.results)?x.results:[],parse=x=>{try{return JSON.parse(x)}catch{return null}},int=x=>Number.isSafeInteger(x)?x:null;
