async function bounded(sql,params=[]){const u=db.usageSnapshot();if(u.rows_read>3000||u.rows_written>5||u.requests>22||u.unknown_ops)throw Error('PREACTION_READ_BOUND');return db.prepare(sql).bind(...params).all();}
